const categories=[['fresh','Fruits & vegetables','tomato','#f1f5e9'],['dairy','Dairy, bread & more','milk','#edf3f8'],['staples','Atta, rice & dal','dal','#f8f0e4'],['snacks','Snacks & munchies','chips','#fbf2df'],['tea','Tea & coffee','tea','#f1ebe3'],['drinks','Drinks & juices','juice','#f8eee6'],['household','Home & cleaning','vim','#edf2ed'],['personal','Personal care','soap','#f4edf4']];
const stores=[{name:'Sri Lakshmi Kirana & General Store',distance:'0.4',rating:'4.8',time:'30–45'},{name:'Ganesh Super Mart',distance:'0.8',rating:'4.7',time:'35–50'},{name:'Sai Balaji General Stores',distance:'1.2',rating:'4.6',time:'40–55'}];
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem('kk-'+key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem('kk-'+key,JSON.stringify(value))}catch{}}
let cart=read('cart',{});cart=Object.fromEntries(Object.entries(cart).filter(([id,q])=>products.some(p=>p.id===id)&&Number.isInteger(q)&&q>0&&q<=20));
let storeIndex=read('store',0);if(!stores[storeIndex])storeIndex=0;
let category='all',query='',expanded=false,toastTimer,returnFocus;
let shopper=read('shopper','');
function money(value){return `₹${value}`}
function quantityControl(id){const q=cart[id]||0;return q?`<div class="stepper"><button data-change="${id}" data-delta="-1" aria-label="Remove one ${esc(products.find(p=>p.id===id).name)}">−</button><span>${q}</span><button data-change="${id}" data-delta="1" aria-label="Add one ${esc(products.find(p=>p.id===id).name)}">+</button></div>`:`<button class="add-button" data-change="${id}" data-delta="1" aria-label="Add ${esc(products.find(p=>p.id===id).name)} to basket">ADD <b>+</b></button>`}
function renderCategories(){ $('#category-grid').innerHTML=categories.map(([id,name,pic,bg])=>`<button class="category ${category===id?'selected':''}" data-category="${id}" aria-pressed="${category===id}"><span class="category-image" style="--bg:${bg}"><img src="${pics[pic]}" alt="" loading="eager"></span>${name}</button>`).join('');}
function renderProducts(){
 let list=products.filter(p=>(category==='all'||p.cat===category)&&`${p.name} ${p.unit} ${categories.find(c=>c[0]===p.cat)?.[1]}`.toLowerCase().includes(query.toLowerCase()));
 const sort=$('#sort').value;if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);
 const limited=!expanded&&category==='all'&&!query&&sort==='popular';const visible=limited?list.slice(0,6):list;
 $('#product-heading').textContent=query?'Search results':category==='all'?'Everyday favourites':categories.find(c=>c[0]===category)[1];
 $('#product-description').textContent=query?`${list.length} ${list.length===1?'essential':'essentials'} found for “${query}”`:category==='all'?'The things you reach for, day after day.':'Everyday essentials from your neighbourhood store.';
 $('#product-grid').innerHTML=visible.map(p=>`<article class="product">${p.mrp>p.price?`<span class="discount">${Math.round((p.mrp-p.price)/p.mrp*100)}% OFF</span>`:''}<div class="product-photo"><img src="${pics[p.id]}" alt="${esc(p.name)}" loading="eager"></div><span class="delivery-time">${icon('clock')} ${stores[storeIndex].time} MINS</span><h3>${p.name}</h3><p class="product-unit">${p.unit}</p><div class="product-bottom"><div class="price">${money(p.price)}${p.mrp>p.price?`<del>${money(p.mrp)}</del>`:''}</div>${quantityControl(p.id)}</div></article>`).join('')||`<div class="empty-results"><h3>No groceries found</h3><p>Try searching for milk, bread, or a product name.</p><button class="outline" data-action="all">Browse all essentials</button></div>`;
 $('#load-more').hidden=!limited;$('#filter-bar').hidden=category==='all'&&!query;$('#filter-text').textContent=query?`Searching for “${query}”`:categories.find(c=>c[0]===category)?.[1];
}
function totals(){const count=Object.values(cart).reduce((a,b)=>a+b,0);const subtotal=products.reduce((a,p)=>a+(cart[p.id]||0)*p.price,0);const savings=products.reduce((a,p)=>a+(cart[p.id]||0)*(p.mrp-p.price),0);const delivery=subtotal>=299||!count?0:20;return{count,subtotal,savings,delivery,total:subtotal+delivery}}
function updateCart(){save('cart',cart);const t=totals();$('#cart-count').hidden=!t.count;$('#cart-count').textContent=t.count;$('#cart-label').textContent=t.count?money(t.subtotal):'My cart';if(!$('#cart-drawer').hidden)renderCart();}
function change(id,delta){const q=(cart[id]||0)+delta;if(q>20){toast('You can add up to 20 of each item.');return}if(q<=0)delete cart[id];else cart[id]=q;const focusSelector=`[data-change="${id}"][data-delta="${delta}"]`;const wasCart=!$('#cart-drawer').hidden;updateCart();renderProducts();(wasCart?$('#cart-body'):$('#product-grid')).querySelector(focusSelector)?.focus({preventScroll:true});}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function close(){if($('#modal').open)$('#modal').close();$('#cart-drawer').hidden=true;$('#scrim').hidden=true;document.body.classList.remove('locked');returnFocus?.focus({preventScroll:true});}
function modal(title,content){close();returnFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-content').innerHTML=content;hydrate($('#modal'));$('#modal').showModal();document.body.classList.add('locked');}
function showCart(){close();returnFocus=document.activeElement;renderCart();$('#scrim').hidden=false;$('#cart-drawer').hidden=false;document.body.classList.add('locked');$('#cart-drawer .close-button').focus();}
function bill(){const t=totals();return `<div class="bill"><h3>Bill details</h3><div><span>Items total</span><span>${money(t.subtotal)}</span></div><div><span>Delivery fee</span><span>${t.delivery?money(t.delivery):'<small>FREE</small>'}</span></div><div class="total"><span>To pay</span><span>${money(t.total)}</span></div></div>${t.savings?`<div class="saving">You’re saving ${money(t.savings)} on your daily essentials.</div>`:''}`}
function renderCart(){const t=totals();$('#cart-subtitle').textContent=`${t.count} ${t.count===1?'item':'items'} · ${stores[storeIndex].name}`;$('#cart-body').innerHTML=t.count?products.filter(p=>cart[p.id]).map(p=>`<div class="cart-row"><img src="${pics[p.id]}" alt="${esc(p.name)}"><div><h3>${p.name}</h3><p>${p.unit}</p><strong>${money(p.price*cart[p.id])}</strong></div>${quantityControl(p.id)}</div>`).join('')+bill():`<div class="empty">${icon('bag')}<h3>A little empty in here.</h3><p>Let’s bring home your everyday favourites.</p><button class="primary" data-action="close">Start shopping ${icon('arrow')}</button></div>`;$('#cart-footer').innerHTML=t.count?`<p>${t.delivery?`Add ${money(299-t.subtotal)} more for free delivery.`:'Your basket qualifies for free delivery.'} Sample prices, inclusive of taxes.</p><button class="primary full" data-action="checkout">Review demo order · ${money(t.total)} ${icon('arrow')}</button>`:'';}
function syncStore(){const s=stores[storeIndex];$('#store-name').textContent=s.name;$('#store-detail').textContent=`Your neighbourhood favourite · ${s.distance} km away`;$('.store-rating').innerHTML=`<span>★ ${s.rating}</span><small>${s.time} min delivery</small>`;save('store',storeIndex);renderProducts();}
function showStores(){modal('Your neighbourhood stores',`<p class="intro">Choose a local kirana to shop from. These are sample stores for this demo.</p>${stores.map((s,i)=>`<button class="store-choice ${i===storeIndex?'current':''}" data-store="${i}">${icon('store')}<span><strong>${s.name}</strong><small>${s.distance} km away · ${s.time} min delivery</small></span><b>${i===storeIndex?'✓':`★ ${s.rating}`}</b></button>`).join('')}`)}
function showList(){const lists=read('lists',[]);modal('Your shopping list',`<p class="intro">Write it just like you would on a piece of paper. Save a list for your next kirana run.</p>${lists.map((l,i)=>`<div class="saved-card"><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p><button class="text-button" data-list-add="${i}">Add matching products to basket ${icon('arrow')}</button><button class="text-button" style="float:right" data-list-remove="${i}">Delete</button></div>`).join('')}<form id="list-form"><label class="field">List name<input name="title" placeholder="This week’s essentials" required maxlength="60"></label><label class="field">What do you need?<textarea name="items" placeholder="Milk – 2 packets&#10;Bread – 1 loaf&#10;Tomatoes – 500 g" required maxlength="2000"></textarea></label><button class="primary full" type="submit">Save shopping list ${icon('check')}</button><p class="helper">Saved on this device. A store isn’t contacted in this demo.</p></form>`)}
function showRecurring(){const schedules=read('schedules',[]);modal('Your regular deliveries',`<p class="intro">Milk in the morning? Bread every Monday? Make a little routine of it.</p>${schedules.map((s,i)=>`<div class="saved-card"><h3>${esc(s.product)} × ${s.quantity}</h3><p>${esc(s.frequency)} · ${esc(s.time)} · starts ${esc(s.date)}</p><button class="text-button" data-schedule-remove="${i}">Remove schedule</button></div>`).join('')}<form id="recurring-form"><label class="field">Your daily essential<select name="product">${products.filter(p=>['dairy','fresh'].includes(p.cat)).map(p=>`<option>${p.name}</option>`).join('')}</select></label><div class="form-row"><label class="field">How often?<select name="frequency"><option>Every day</option><option>Every other day</option><option>Every week</option><option>Every month</option></select></label><label class="field">Quantity<input type="number" name="quantity" value="1" min="1" max="10" required></label></div><div class="form-row"><label class="field">Start date<input type="date" name="date" min="${localDate()}" value="${localDate()}" required></label><label class="field">Preferred time<select name="time"><option>7 am – 9 am</option><option>9 am – 12 pm</option><option>5 pm – 8 pm</option></select></label></div><button class="primary full">Save delivery schedule ${icon('repeat')}</button><p class="helper">Demo schedule saved on this device. No real deliveries or charges are created.</p></form>`)}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function showAccount(){const orders=read('orders',[]);modal(shopper?`Hello, ${shopper}`:'A familiar face, a familiar store.',shopper?`<p class="intro">Your saved activity on this device.</p><button class="outline" data-action="list">Shopping lists</button> <button class="outline" data-action="recurring">Regular deliveries</button><h3 style="margin:25px 0 15px;font-size:14px">Your demo orders</h3>${orders.length?orders.slice().reverse().map(o=>`<div class="saved-card"><h3>${esc(o.id)} · ${money(o.total)}</h3><p>${esc(o.date)}<br>${esc(o.store)}<br>${esc(o.summary)}</p><span class="helper">Demo order · No payment or delivery</span></div>`).join(''):'<p class="intro">No orders yet. Your next favourite is a few taps away.</p>'}<button class="text-button" data-action="signout" style="margin-top:20px">Switch profile</button>`:`<p class="intro">What should we call you? Keep your shopping lists and demo orders together on this device.</p><form id="account-form"><label class="field">Your name<input name="name" required maxlength="35" placeholder="Enter your first name" autocomplete="given-name"></label><button class="primary full">Continue ${icon('arrow')}</button><p class="helper">This creates a local demo profile. No phone number or password needed.</p></form>`)}
function checkout(){if(!totals().count)return;modal('Review your demo order',`<p class="intro">From ${esc(stores[storeIndex].name)} · Estimated ${stores[storeIndex].time} minutes in a live service.</p>${bill()}<form id="checkout-form"><label class="field">Delivery label<input name="label" placeholder="e.g. Hostel reception or Home" required maxlength="80"></label><button class="primary full">Place demo order · ${money(totals().total)} ${icon('arrow')}</button><p class="helper">This is a demonstration. No store will receive an order, no payment is taken, and no delivery is scheduled. Please use a sample delivery label.</p></form>`)}
function showPartner(){modal('Bring your kirana online',`<p class="intro">Your store. Your customers. A simpler way to stay connected.</p><div class="saved-card"><h3>Less listing. More selling.</h3><p>Build a catalogue from distributor invoices, keep online and offline stock together, and manage local orders in one place.</p></div><form id="partner-form"><label class="field">Store name<input name="store" placeholder="Your kirana store" required maxlength="80"></label><label class="field">Neighbourhood<input name="area" placeholder="e.g. Bachupally, Hyderabad" required maxlength="80"></label><button class="primary full">Preview my store ${icon('store')}</button><p class="helper">Demo preview only. No application is sent or account created.</p></form>`)}
const actions={home:()=>{category='all';query='';expanded=false;$('#search').value='';renderCategories();renderProducts();window.scrollTo({top:0,behavior:'smooth'})},browse:()=>$('#categories').scrollIntoView({behavior:'smooth'}),all:()=>{category='all';query='';expanded=true;$('#search').value='';renderCategories();renderProducts();$('#products').scrollIntoView({behavior:'smooth'})},more:()=>{expanded=true;renderProducts()},cart:showCart,close,stores:showStores,list:showList,recurring:showRecurring,account:showAccount,checkout,partner:showPartner,signout:()=>{shopper='';save('shopper','');$('#account-label').textContent='Account';showAccount()},location:()=>modal('Where’s your neighbourhood?',`<p class="intro">Set a neighbourhood for your demo. Sample kiranas are based in Bachupally, Hyderabad.</p><form id="location-form"><label class="field">Neighbourhood or pincode<input name="area" value="${esc(read('location','Bachupally, Hyderabad'))}" placeholder="Enter a neighbourhood" required maxlength="60"></label><button class="primary full">Save neighbourhood ${icon('check')}</button><p class="helper">Location is saved on this device. Service availability is illustrative.</p></form>`),about:()=>modal('A little closer to home.',`<p class="intro">KiranaKottu connects you with the neighbourhood stores you know and trust. Shop everyday essentials, keep a grocery list, and plan your regular deliveries.</p><div class="saved-card"><h3>Built around local kiranas</h3><p>Our idea is simple: give local shopkeepers the convenience of online ordering while keeping the personal care of your familiar corner store.</p></div><p class="helper">This prototype demonstrates the customer experience using sample data and local device storage. Invoice extraction, shared live inventory, payments, and fulfilment require backend integrations.</p>`)};
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){actions[a.dataset.action]?.();return}const c=e.target.closest('[data-category]');if(c){category=c.dataset.category;query='';$('#search').value='';expanded=true;renderCategories();renderProducts();$('#products').scrollIntoView({behavior:'smooth'});return}const q=e.target.closest('[data-change]');if(q){change(q.dataset.change,Number(q.dataset.delta));return}const s=e.target.closest('[data-store]');if(s){storeIndex=Number(s.dataset.store);syncStore();close();toast(`Now shopping from ${stores[storeIndex].name}`);return}const lr=e.target.closest('[data-list-remove]');if(lr){const lists=read('lists',[]);lists.splice(Number(lr.dataset.listRemove),1);save('lists',lists);showList();return}const sr=e.target.closest('[data-schedule-remove]');if(sr){const schedules=read('schedules',[]);schedules.splice(Number(sr.dataset.scheduleRemove),1);save('schedules',schedules);showRecurring();return}const la=e.target.closest('[data-list-add]');if(la){const list=read('lists',[])[Number(la.dataset.listAdd)];let found=0;list.text.split(/\n|,/).forEach(line=>{const words=line.toLowerCase();let p=products.find(p=>p.name.toLowerCase().includes(words.trim()));if(!p){p=products.find(p=>p.name.toLowerCase().split(/\s+/).some(w=>w.length>3&&words.includes(w)));}if(p){const n=words.match(/(?:×|x|–|-|:)\s*(\d{1,2})(?:\s*(?:packets?|packs?|loaves?|pcs?|units?))?\s*$/);const amount=n?Math.min(20,Number(n[1])||1):1;cart[p.id]=Math.min(20,(cart[p.id]||0)+amount);found++}});updateCart();renderProducts();if(found){showCart();toast(`${found} matching ${found===1?'product':'products'} added. Review quantities in your basket.`)}else toast('No matching products found. Try product names like milk or bread.')}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const data=Object.fromEntries(new FormData(f));if(f.id==='location-form'){if(!data.area.trim()){toast('Please enter a neighbourhood.');return}save('location',data.area.trim());$('#location-text').textContent=data.area.trim();close();toast('Your neighbourhood is saved.')}if(f.id==='account-form'){if(!data.name.trim()){toast('Please enter your name.');return}shopper=data.name.trim();save('shopper',shopper);$('#account-label').textContent=shopper;showAccount()}if(f.id==='list-form'){if(!data.title.trim()||!data.items.trim()){toast('Please add a list name and at least one item.');return}const lists=read('lists',[]);lists.push({title:data.title.trim(),text:data.items.trim()});save('lists',lists);showList();toast('Shopping list saved.')}if(f.id==='recurring-form'){const schedules=read('schedules',[]);schedules.push(data);save('schedules',schedules);showRecurring();toast('Demo delivery schedule saved.')}if(f.id==='checkout-form'){const t=totals();if(!t.count)return;if(!data.label.trim()){toast('Please enter a sample delivery label.');return}const orders=read('orders',[]);const order={id:`KK-${Date.now().toString().slice(-6)}`,date:new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}),store:stores[storeIndex].name,total:t.total,summary:products.filter(p=>cart[p.id]).map(p=>`${p.name} × ${cart[p.id]}`).join(', ')};orders.push(order);save('orders',orders);cart={};updateCart();renderProducts();modal('Your demo order is ready',`<div class="success-content"><div class="success-symbol">${icon('check')}</div><h3>That’s a basket well filled.</h3><p>${esc(order.id)} · ${money(order.total)}<br>Saved to your demo order history.</p><div class="saved-card"><p>No payment was taken. This is a sample order and won’t be delivered.</p></div><button class="primary full" data-action="account">View demo orders ${icon('arrow')}</button></div>`)}if(f.id==='partner-form'){modal('Your store preview',`<div class="success-content"><div class="success-symbol">${icon('store')}</div><h3>${esc(data.store)}</h3><p>${esc(data.area)}</p></div><div class="saved-card"><h3>Your next steps</h3><p>1. Upload a distributor invoice.<br>2. Verify products and selling prices.<br>3. Publish your catalogue.<br>4. Accept nearby orders.</p></div><p class="helper">This is an onboarding preview. Live merchant registration, invoice extraction, and stock management are planned integrations.</p>`)}});
$('#search').addEventListener('input',e=>{query=e.target.value.trim();category='all';expanded=true;renderCategories();renderProducts();});$('#search').addEventListener('keydown',e=>{if(e.key==='Enter')$('#products').scrollIntoView({behavior:'smooth'})});$('#sort').addEventListener('change',renderProducts);$('#scrim').addEventListener('click',close);$('#modal').addEventListener('close',()=>{if(!$('#modal').open&&$('#cart-drawer').hidden)document.body.classList.remove('locked')});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#search').focus()}if(e.key==='Tab'&&!$('#cart-drawer').hidden){const focusable=Array.from($('#cart-drawer').querySelectorAll('button,a,input,select,textarea')).filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
hydrate();renderCategories();renderProducts();syncStore();updateCart();$('#location-text').textContent=read('location','Bachupally, Hyderabad');if(shopper)$('#account-label').textContent=shopper;

document.addEventListener('error',event=>{const image=event.target;if(image.tagName==='IMG'){const fallback=document.createElement('span');fallback.className='image-fallback';fallback.innerHTML=icon(image.closest('.category-image')?'bag':'store')+'<span>Image unavailable</span>';image.replaceWith(fallback);}},true);
